    /**
     * @covers AdminZone\ParovacFaktur::reorderInvoicesByAge
     */
    public function testReorderInvoicesByAge()
    {
        $now = time();
        $initialData = ['typDokl' => \AbraFlexi\Functions::code('FAKTURA'),
            'popis' => 'testSettleProforma', 'sumZklZakl' => 1000, 'firma' => 'code:VITEX',
            'varSym' => $now];

        $now = time();
        $payment = self::createPayment(['sumZklZakl' => 4000, 'bezPolozek' => true,
                    'varSym' => $now]);

        $day = new \DateTime();

        $day->modify('-1 day');
        sleep(1);
        $invoice3 = \Test\AbraFlexi\FakturaVydanaTest::makeTestInvoice(array_merge([
                    'datVyst' => \AbraFlexi\RO::dateToFlexiDate($day)],
                                $initialData));

        $day->modify('-1 day');
        sleep(1);
        $invoice2 = \Test\AbraFlexi\FakturaVydanaTest::makeTestInvoice(array_merge([
                    'datVyst' => \AbraFlexi\RO::dateToFlexiDate($day)],
                                $initialData));

        $day->modify('-1 day');
        sleep(1);
        $invoice1 = \Test\AbraFlexi\FakturaVydanaTest::makeTestInvoice(array_merge([
                    'datVyst' => \AbraFlexi\RO::dateToFlexiDate($day)],
                                $initialData));

        $reordered = ParovacFaktur::reorderInvoicesByAge([$invoice2->getData(), $invoice3->getData(),
                    $invoice1->getData()]);

        $this->assertEquals([$invoice1->getDataValue('kod') => $invoice1->getData(),
            $invoice2->getDataValue('kod') => $invoice2->getData(), $invoice3->getDataValue('kod') => $invoice3->getData()],
                $reordered);
    }

