        $fakturaA = self::makeInvoice(['typDokl' => \AbraFlexi\Functions::code('FAKTURA'),
                    'popis' => 'testSettleProforma', 'sumZklZakl' => 1000, 'firma' => 'code:VITEX',
                    'varSym' => $now]);
        $paymentA = self::createPayment(['sumZklZakl' => 1000, 'bezPolozek' => true,
                    'varSym' => $now]);

        sleep(1);

        $fakturaB = self::makeInvoice(['typDokl' => \AbraFlexi\Functions::code('FAKTURA'),
                    'popis' => 'testSettleProforma', 'sumZklZakl' => 1000, 'firma' => 'code:VITEX',
                    'varSym' => $now]);
        $paymentB = self::createPayment(['sumZklZakl' => 1000, 'bezPolozek' => true,
                    'varSym' => $now]);

        $found = $this->object->searchInvoices(['varSym' => $now]);

        $this->assertTrue(2 == count($found));
        $this->assertArrayHasKey(fb::uncode($fakturaA->getRecordCode()), $found);
        $this->assertArrayHasKey(fb::uncode($fakturaB->getRecordCode()), $found);
    }

    /**
     * @covers AdminZone\ParovacFaktur::notifyOrder
     */
    public function testNotifyOrder()
    {
        $order = new \AbraFlexi\RO(1,
                ['evidence' => 'objednavka-prijata', 'ignore404' => true]);
        $order->loadFromAbraFlexi($order->getNextRecordID());
        $this->assertTrue($this->object->notifyOrder($order));
    }
